//! Build/check portable library proof artifacts with the compiler's parser
//! and binder. Generated bytes are never edited by hand.
use std::path::PathBuf;
use tsc_binder::library_image::build_command_library_image;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut args = std::env::args_os().skip(1);
    let output = PathBuf::from(args.next().ok_or("usage: library_image OUTPUT [--check]")?);
    let check = match args.next() {
        None => false,
        Some(arg) if arg == "--check" => true,
        _ => return Err("usage: library_image OUTPUT [--check]".into()),
    };
    if args.next().is_some() {
        return Err("unexpected argument".into());
    }
    let directory = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(
        "../../vendor/typescript-native/7.1.0-dev-aa814927/upstream/tsc/internal/bundled/libs",
    );
    let mut files: Vec<_> = std::fs::read_dir(directory)?
        .map(|e| e.map(|e| e.path()))
        .collect::<std::io::Result<_>>()?;
    files.retain(|p| p.extension().is_some_and(|e| e == "ts"));
    files.sort();
    if files.len() != 116 {
        return Err("pinned library catalog changed".into());
    }
    if !check {
        std::fs::create_dir_all(&output)?;
    }
    let mut bytes = 0;
    let mut artifacts = 0;
    for path in files {
        let name = path
            .file_name()
            .ok_or("library has no name")?
            .to_str()
            .ok_or("library name is not UTF-8")?;
        let text = std::fs::read_to_string(&path)?;
        let label = "types";
        let image = build_command_library_image(&format!("bundled:///libs/{name}"), &text)?;
        for (part, data) in [
            ("parsed", image.syntax),
            ("edits", image.edits),
            ("binding", image.binding),
        ] {
            let destination = output.join(format!("{name}.{label}.{part}.bin"));
            if check {
                if std::fs::read(&destination)? != data {
                    return Err(format!("stale library image: {}", destination.display()).into());
                }
            } else {
                std::fs::write(&destination, &data)?;
            }
            bytes += data.len();
            artifacts += 1;
        }
    }
    println!("{artifacts} artifacts, {bytes} bytes, check={check}");
    Ok(())
}
